descriptor.templateCss:
:host{display:block;width:100%;height:100%;min-width:0;min-height:0;overflow:hidden}
*{box-sizing:border-box}
.kp-root{--kp-bg:#111820;--kp-text:#edf3f8;--kp-muted:#9aa9b8;width:100%;height:100%;padding:3px 10px;display:flex;flex-direction:column;gap:8px;overflow:hidden;border-radius:inherit;background:transparent;color:var(--kp-text);font-family:Roboto,Arial,sans-serif;position:relative;container-type:inline-size}
.kp-themebg.kp-industrial{background:linear-gradient(145deg,#17232e,#101820)}
.kp-light{--kp-bg:#fff;--kp-text:#263445;--kp-muted:#778596}
.kp-themebg.kp-light{background:linear-gradient(145deg,#fff,#f3f6f9)}
.kp-header{display:flex;align-items:center;gap:9px;min-height:32px;flex:0 0 auto}
.kp-icon{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:9px;border:1px solid transparent;flex:0 0 auto}
.kp-icon tb-icon,.kp-icon .mat-icon,.kp-icon mat-icon{font-size:20px;width:20px;height:20px;color:inherit}
:host ::ng-deep .kp-icon tb-icon,:host ::ng-deep .kp-icon .mat-icon,:host ::ng-deep .kp-icon mat-icon,:host ::ng-deep .kp-icon svg{color:inherit;fill:currentColor;font-size:20px;width:20px;height:20px;line-height:20px}
.kp-title{font-size:13px;font-weight:700;letter-spacing:.2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.kp-body{flex:1 1 0;min-height:0;container-type:size}
.kp-inner{height:100%;display:flex;flex-direction:column;justify-content:center;gap:7px;gap:clamp(3px,6.6cqh,18px)}
.kp-label:empty{display:none}
.kp-label{font-size:10px;font-size:clamp(8px,min(8.9cqh,3.4cqw),18px);color:var(--kp-muted);font-weight:650;letter-spacing:.5px;text-transform:uppercase}
.kp-value-line{display:flex;align-items:baseline;gap:.14em;min-width:0;font-size:clamp(28px,6vw,48px)}
.kp-value{font-size:1em;font-weight:800;line-height:1;letter-spacing:-1.6px;font-variant-numeric:tabular-nums;white-space:nowrap}
.kp-unit{font-weight:650;line-height:1;color:var(--kp-muted);white-space:nowrap}
.kp-badge{margin-left:auto;align-self:center;font-size:12px;font-size:clamp(10px,11cqh,20px);font-weight:800;padding:3px 10px;border-radius:999px;white-space:nowrap;font-variant-numeric:tabular-nums}
.kp-bar{position:relative;width:100%;border-radius:999px;overflow:hidden;flex:0 0 auto}
.kp-track{position:absolute;left:0;top:0;right:0;bottom:0;border-radius:inherit}
.kp-fill{position:absolute;left:0;top:0;bottom:0;border-radius:inherit;transition:width .6s ease;background-image:linear-gradient(180deg,rgba(255,255,255,.32),rgba(255,255,255,0) 60%)}
.kp-summary{font-size:12px;font-size:clamp(9px,min(11.8cqh,4.3cqw),22px);color:var(--kp-muted);white-space:pre-wrap;line-height:1.4}
.kp-summary .kp-strong{font-weight:750;color:var(--kp-text)}
.kp-no-data{position:absolute;left:0;right:0;bottom:3px;text-align:center;color:var(--kp-muted);font-size:9px;pointer-events:none}
@container (max-width:230px){.kp-title{font-size:11px}.kp-badge{padding:2px 7px}}

descriptor.controllerScript:
var kp = {dead:false,neutral:false};
function kpNum(v){
  if(v===null||v===undefined||v==='')return null;
  var n=typeof v==='number'?v:parseFloat(String(v).replace(/\s/g,'').replace(',','.'));
  return isFinite(n)?n:null;
}
function kpClamp(v,a,b){return Math.max(a,Math.min(b,v));}
function kpFmt(n,dec,fmt){
  if(n===null||n===undefined)return '—';
  dec=kpClamp(Math.round(dec),0,6);
  if(fmt==='none')return n.toFixed(dec);
  return n.toLocaleString(fmt==='es'?'de-DE':'en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec,useGrouping:true});
}
function kpHexA(hex,a){
  var h=String(hex||'').trim().replace('#','');
  if(h.length===3)h=h.charAt(0)+h.charAt(0)+h.charAt(1)+h.charAt(1)+h.charAt(2)+h.charAt(2);
  if(!/^[0-9a-fA-F]{6}$/.test(h))return 'rgba(128,140,152,'+a+')';
  return 'rgba('+parseInt(h.slice(0,2),16)+','+parseInt(h.slice(2,4),16)+','+parseInt(h.slice(4,6),16)+','+a+')';
}
function kpContrast(hex){
  var h=String(hex||'').trim().replace('#','');
  if(h.length===3)h=h.charAt(0)+h.charAt(0)+h.charAt(1)+h.charAt(1)+h.charAt(2)+h.charAt(2);
  if(!/^[0-9a-fA-F]{6}$/.test(h))return '#ffffff';
  var l=(0.299*parseInt(h.slice(0,2),16)+0.587*parseInt(h.slice(2,4),16)+0.114*parseInt(h.slice(4,6),16))/255;
  return l>0.62?'#14181d':'#ffffff';
}
function kpFindSeries(data,keyName,index){
  if(keyName){
    for(var i=0;i<data.length;i++){
      var k=data[i]&&data[i].dataKey?data[i].dataKey:{};
      if((k.name||k.label)===keyName||k.label===keyName)return data[i];
    }
    return null;
  }
  return data[index]||null;
}
function kpLast(series){
  if(!series||!Array.isArray(series.data)||!series.data.length)return null;
  var p=series.data[series.data.length-1];
  return p&&p.length>=2?kpNum(p[1]):null;
}
var kpPatched=[];
function kpRestore(){
  kpPatched.forEach(function(p){
    if(p.prev===null||p.prev==='')p.el.style.removeProperty('background-color');
    else p.el.style.setProperty('background-color',p.prev,p.prio);
  });
  kpPatched=[];kp.neutral=false;
}
function kpNeutralize(){
  kpRestore();
  try{
    var el=self.ctx.$container&&self.ctx.$container[0];
    for(var i=0;el&&i<4;i++,el=el.parentElement){
      var cs=window.getComputedStyle(el),bg=cs.backgroundColor;
      if(bg&&bg!=='transparent'&&bg!=='rgba(0, 0, 0, 0)'){
        kpPatched.push({el:el,prev:el.style.getPropertyValue('background-color'),prio:el.style.getPropertyPriority('background-color')});
        el.style.setProperty('background-color','transparent','important');
      }
      var rad=cs.borderTopLeftRadius,cls=typeof el.className==='string'?el.className:'';
      if((rad&&rad!=='0px')||/tb-widget/.test(cls))break;
    }
    kp.neutral=true;
  }catch(e){}
}
function kpRadius(){
  var ctx=self.ctx,cfg=ctx.widgetConfig||{},r=cfg.borderRadius;
  if(typeof r==='number')r=r+'px';
  if(typeof r==='string'&&r.trim()!=='')return r.trim();
  try{
    var el=ctx.$container&&ctx.$container[0];
    for(var i=0;el&&i<8;i++,el=el.parentElement){
      var br=window.getComputedStyle(el).borderTopLeftRadius;
      if(br&&br!=='0px')return br;
    }
  }catch(e){}
  return null;
}
function kpBuild(){
  var ctx=self.ctx,s=ctx.settings||{},data=ctx.data||[];
  var theme=s.theme==='executive'?'executive':'industrial';
  var decimals=kpClamp(kpNum(s.decimals)===null?0:kpNum(s.decimals),0,4);
  var pdec=kpClamp(kpNum(s.percentDecimals)===null?0:kpNum(s.percentDecimals),0,3);
  var fmt=s.numberFormat==='es'||s.numberFormat==='none'?s.numberFormat:'en';
  var barColor=s.barColor||'#F2C300';

  var value=kpLast(kpFindSeries(data,(s.valueKey||'').trim(),0));
  var refSource=s.referenceSource==='datakey'?'datakey':'manual';
  var ref=refSource==='datakey'?kpLast(kpFindSeries(data,(s.referenceKey||'').trim(),1)):kpNum(s.referenceManual===undefined?10000:s.referenceManual);
  var has=value!==null,hasRef=ref!==null&&ref>0;
  var pct=has&&hasRef?value/ref*100:null;
  var pctShown=pct===null?null:(s.clampPercent===false?pct:Math.min(pct,100));
  if(pctShown!==null&&pctShown<0)pctShown=0;
  var barPct=pct===null?0:kpClamp(pct,0,100);

  var unit=(s.unit||'').trim();
  var refUnit=s.referenceSameUnit===false?(s.referenceUnit||'').trim():unit;
  var valueText=has?kpFmt(value,decimals,fmt):'—';
  var refText=hasRef?kpFmt(ref,decimals,fmt):'—';
  var pctText=pctShown===null?'—':kpFmt(pctShown,pdec,fmt);
  var connector=(s.summaryConnector===undefined?'de':String(s.summaryConnector)).trim();
  var suffix=(s.summaryText===undefined?'de la capacidad':String(s.summaryText)).trim();

  var seg=[];
  seg.push({t:valueText,b:true});
  if(unit)seg.push({t:' '+unit});
  seg.push({t:' '+(connector?connector+' ':'')});
  seg.push({t:refText,b:true});
  if(refUnit)seg.push({t:' '+refUnit});
  seg.push({t:', '});
  seg.push({t:pctText+'%',b:true,c:barColor});
  if(suffix)seg.push({t:' '+suffix});

  var wEm=0,vt=String(valueText);
  for(var ci=0;ci<vt.length;ci++){var ch=vt.charAt(ci);wEm+=(ch===','||ch==='.')?0.3:(ch==='-'?0.4:0.62);}
  wEm+=unit?(unit.length*0.6*(kpClamp(kpNum(s.unitSize)===null?38:kpNum(s.unitSize),10,100)/100)+0.14):0;
  var labelOn=!!(s.showLabel===false?'':(s.valueLabel===undefined?'VALOR ACTUAL':String(s.valueLabel===null?'':s.valueLabel).trim()));
  var badgeOn=s.showPercentBadge!==false&&pct!==null;
  var wLimit=Math.max(8,(100-(badgeOn?24:4))/Math.max(1.4,wEm));
  var valueFont='clamp(18px,min('+(labelOn?39.5:52)+'cqh,'+wLimit.toFixed(1)+'cqw),150px)';
  var wantNeutral=s.cardBackground!=='transparent'&&s.clearNativeBg!==false;
  if(wantNeutral&&!kp.neutral)kpNeutralize();else if(!wantNeutral&&kp.neutral)kpRestore();
  var thick={thin:3,normal:6,thick:10}[s.barThickness]||6;
  var iconColor=s.iconColorMode==='custom'&&s.iconColor?s.iconColor:barColor;
  var iconStyle=['tile','solid','outline','plain'].indexOf(s.iconStyle)>=0?s.iconStyle:'tile';
  var iconBg=kpHexA(iconColor,.14),iconBorder=kpHexA(iconColor,.3),iconFg=iconColor;
  if(iconStyle==='solid'){iconBg=iconColor;iconBorder=iconColor;iconFg=kpContrast(iconColor);}
  else if(iconStyle==='outline'){iconBg='transparent';iconBorder=kpHexA(iconColor,.65);}
  else if(iconStyle==='plain'){iconBg='transparent';iconBorder='transparent';}
  var unitScale=kpClamp(kpNum(s.unitSize)===null?38:kpNum(s.unitSize),10,100)/100;
  var legacy=kpNum(s.contentPadding);
  var padX=kpClamp(kpNum(s.paddingX)===null?(legacy===null?10:legacy):kpNum(s.paddingX),0,40);
  var padY=kpClamp(kpNum(s.paddingY)===null?3:kpNum(s.paddingY),0,40);
  var hasHeader=s.showHeader!==false&&((s.showTitle!==false&&String(s.title===undefined?'KPI':s.title).length>0)||(s.showIcon!==false&&!!(s.icon||'insights')));
  ctx.$scope.vm={
    theme:theme,themeBg:s.cardBackground!=='transparent',radius:kpRadius(),
    showHeader:s.showHeader!==false,showTitle:s.showTitle!==false,title:s.title===undefined?'KPI':s.title,
    hasHeader:hasHeader,padTop:hasHeader?kpClamp(kpNum(s.paddingTop)===null?6:kpNum(s.paddingTop),0,40):padY,padSide:padX,padBottom:padY,
    showIcon:s.showIcon!==false,icon:s.icon||'insights',
    badgeBg:kpHexA(barColor,.14),iconColor:iconFg,iconBg:iconBg,iconBorder:iconBorder,unitScale:unitScale,
    valueLabel:s.showLabel===false?'':(s.valueLabel===undefined?'VALOR ACTUAL':String(s.valueLabel===null?'':s.valueLabel).trim()),
    valueText:valueText,valueFont:valueFont,unit:unit,hasData:has,
    valueColor:s.valueUsesBarColor===true?barColor:null,
    showPercentBadge:s.showPercentBadge!==false,hasPct:pct!==null,pctText:pctText,
    showBar:s.showBar!==false,barColor:barColor,barPct:barPct,barHeight:thick,
    trackOpacity:kpClamp(kpNum(s.trackOpacity)===null?0.22:kpNum(s.trackOpacity),0.05,0.6),
    showSummary:s.showSummary!==false,summary:has&&hasRef?seg:[{t:has?'Sin valor máximo válido':' '}],
    noDataText:s.noDataText===undefined?'Sin datos':s.noDataText
  };
  if(ctx.detectChanges)ctx.detectChanges();
}
self.onInit=function(){kp.dead=false;self.ctx.$scope.vm={theme:'industrial',themeBg:true,hasHeader:true,padTop:6,padSide:10,padBottom:3,radius:null,showHeader:true,showTitle:true,title:'KPI',barColor:'#F2C300',summary:[],hasData:false,valueText:'—'};kpBuild();};
self.onDataUpdated=function(){if(!kp.dead)kpBuild();};
self.onLatestDataUpdated=function(){if(!kp.dead)kpBuild();};
self.onResize=function(){if(!kp.dead)kpBuild();};
self.onDestroy=function(){kp.dead=true;kpRestore();};
self.typeParameters=function(){return{maxDatasources:1,maxDataKeys:2,datasourcesOptional:true,dataKeysOptional:true,previewWidth:'380px',previewHeight:'190px'};};

